// Normalizador de datos - maneja todas las estructuras posibles
function extraerDatos(input) {
  // Casos posibles de entrada
  let datos;

  // Caso 1: Webhook con body
  if (input.body) {
    datos = input.body;
  }
  // Caso 2: Datos directos
  else {
    datos = input;
  }

  // Si es array, tomar el primer elemento
  if (Array.isArray(datos)) {
    datos = datos[0];
  }

  // Si tiene query, extraerlo
  if (datos.query) {
    // Si query es string, parsearlo
    if (typeof datos.query === 'string') {
      datos = JSON.parse(datos.query);
    } else {
      datos = datos.query;
    }
  }

  // Si después del parse es array, tomar primer elemento
  if (Array.isArray(datos)) {
    datos = datos[0];
  }

  return datos;
}

// Obtener datos de entrada
const inputData = $json;
const solicitud = extraerDatos(inputData);

// Devolver datos limpios
return [{
  json: solicitud
}];

const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;

