// Obtener TODOS los turnos ocupados usando .all()
const pilar1Ocupados = $('ASAHI_1').all().map(item => item.json).flat();
const pilar2Ocupados = $('ASAHI_2').all().map(item => item.json).flat();

// Función para verificar si hay conflicto de horarios
function tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, ocupados) {
  if (!Array.isArray(ocupados)) {
    return false;
  }

  return ocupados.some(ocupado => {
    // Mismo día
    if (ocupado.dia !== solicitudFecha) return false;

    // Convertir horarios a minutos para comparación más fácil
    const solicitudInicioMin = timeToMinutes(solicitudInicio);
    const solicitudFinMin = timeToMinutes(solicitudFin);
    const ocupadoInicioMin = timeToMinutes(ocupado.inicio);
    const ocupadoFinMin = timeToMinutes(ocupado.final);

    // Verificar solapamiento (cualquier intersección)
    return (solicitudInicioMin < ocupadoFinMin && solicitudFinMin > ocupadoInicioMin);
  });
}

// Convertir tiempo HH:MM a minutos
function timeToMinutes(timeStr) {
  const [hours, minutes] = timeStr.split(':').map(Number);
  return hours * 60 + minutes;
}

// Extraer fecha y horarios de la solicitud
let solicitudFecha, solicitudInicio, solicitudFin;

try {
  // Verificar que fecha y fin existan (en minúsculas)
  if (!solicitud.fecha || !solicitud.fin) {
    throw new Error('Faltan datos de fecha o fin en la solicitud');
  }

  // Extraer desde formato ISO: "2025-10-07T10:30:00"
  const [fecha, horaInicio] = solicitud.fecha.split('T');
  const [fechaFin, horaFin] = solicitud.fin.split('T');

  solicitudFecha = fecha; // "2025-10-07"
  solicitudInicio = horaInicio.substring(0, 5); // "10:30"
  solicitudFin = horaFin.substring(0, 5); // "12:00"

} catch (parseError) {
  return [{
    json: {
      error: `Error al procesar fechas: ${parseError.message}`,
      solicitud: solicitud
    }
  }];
}

// IDs de los calendarios
const ASAHI_1_ID = "7fe32e4f1b50f7dc87ace1e558875a48a76f9267dcc28345c1c256eb091bda72@group.calendar.google.com";
const ASAHI_2_ID = "7fe32e4f1b50f7dc87ace1e558875a48a76f9267dcc28345c1c256eb091bda72@group.calendar.google.com";

// Verificar disponibilidad
const pilar1Disponible = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar1Ocupados);
const pilar2Disponible = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar2Ocupados);

let calendarioElegido;
let error = null;

if (pilar1Disponible && pilar2Disponible) {
  // Ambos disponibles, elegir ASAHI_1 por defecto
  calendarioElegido = ASAHI_1_ID;
} else if (pilar1Disponible) {
  calendarioElegido = ASAHI_1_ID;
} else if (pilar2Disponible) {
  calendarioElegido = ASAHI_2_ID;
} else {
  // Ninguno disponible
  error = "No hay calendarios disponibles para el horario solicitado";
}

// Preparar respuesta
if (error) {
  return [{
    json: {
      error: error,
      solicitud: solicitud
    }
  }];
} else {
  const respuesta = {
    ...solicitud,
    Calendar: calendarioElegido
  };

  return [{
    json: respuesta
  }];
}

